TEST(ImageIO, DetectsTiffAndReadsRgb) {
    const ImageInfo info = read_image_info(fixture("rgb8.tiff"));
    EXPECT_EQ(info.format, ImageFormat::Tiff);
    EXPECT_EQ(info.width, 64);
    EXPECT_EQ(info.height, 48);
    EXPECT_EQ(info.channels, 3);
    EXPECT_EQ(info.bit_depth, 8);

    const Image image = read_image(fixture("rgb8.tiff"));
    ASSERT_EQ(image.channels(), 3);
    for (int y = 0; y < 48; y += 7) {
        for (int x = 0; x < 64; x += 5) {
            int expected[3];
            rgb_value(x, y, expected);
            for (int c = 0; c < 3; ++c) {
                ASSERT_EQ(image.at(x, y, c), static_cast<std::uint8_t>(expected[c]));
            }
        }
    }
}

TEST(ImageIO, SixteenBitTiffRoundsToEight) {
    const ImageInfo info = read_image_info(fixture("grey16.tiff"));
    EXPECT_EQ(info.format, ImageFormat::Tiff);
    EXPECT_EQ(info.bit_depth, 16);
    EXPECT_EQ(info.channels, 1);

    const Image image = read_image(fixture("grey16.tiff"));
    ASSERT_EQ(image.channels(), 1);
    for (int y = 0; y < 48; ++y) {
        for (int x = 0; x < 64; ++x) {
            ASSERT_EQ(image.at(x, y), round16(static_cast<std::uint32_t>(grey16_value(x, y))))
                << "at " << x << "," << y;
        }
    }
}

TEST(ImageIO, BigEndianTiffDecodesLikeTheLittleEndianOne) {
    // tiffcp -B writes an MM (big-endian) file; every multi-byte tag must be
    // read in that order, and the pixels must match the LE twin exactly.
    const std::string be = fixture("rgb8_be.tiff");
    if (!std::filesystem::exists(be)) {
        GTEST_SKIP() << "rgb8_be.tiff not generated (tiffcp unavailable)";
    }
    // Magic: 'M' 'M' 0x00 0x2A.
    const std::vector<std::uint8_t> head = read_bytes(be);
    ASSERT_GE(head.size(), 4U);
    EXPECT_EQ(head[0], 'M');
    EXPECT_EQ(head[1], 'M');
    EXPECT_EQ(head[2], 0x00);
    EXPECT_EQ(head[3], 0x2A);

    const ImageInfo info = read_image_info(be);
    EXPECT_EQ(info.format, ImageFormat::Tiff);
    EXPECT_EQ(info.width, 64);
    EXPECT_EQ(info.height, 48);
    EXPECT_EQ(info.channels, 3);

    const Image image = read_image(be);
    const Image le = read_image(fixture("rgb8.tiff"));
    ASSERT_EQ(image.channels(), 3);
    for (int y = 0; y < 48; y += 3) {
        for (int x = 0; x < 64; x += 3) {
            for (int c = 0; c < 3; ++c) {
                ASSERT_EQ(image.at(x, y, c), le.at(x, y, c)) << "at " << x << "," << y;
            }
        }
    }
}

TEST(ImageIO, TiledSixteenBitTiffMatchesTheStrippedOne) {
    // same pixels, different storage: the tile path must agree with the strip
    // path exactly, including the 16->8 rounding.
    const std::string tiled = fixture("grey16_tiled.tiff");
    if (!std::filesystem::exists(tiled)) {
        GTEST_SKIP() << "grey16_tiled.tiff not generated (tiffcp unavailable)";
    }
    const ImageInfo info = read_image_info(tiled);
    EXPECT_EQ(info.format, ImageFormat::Tiff);
    EXPECT_EQ(info.width, 64);
    EXPECT_EQ(info.height, 48);
    EXPECT_EQ(info.bit_depth, 16);

    const Image image = read_image(tiled);
    const Image stripped = read_image(fixture("grey16.tiff"));
    ASSERT_EQ(image.channels(), 1);
    for (int y = 0; y < 48; ++y) {
        for (int x = 0; x < 64; ++x) {
            ASSERT_EQ(image.at(x, y), stripped.at(x, y)) << "at " << x << "," << y;
            ASSERT_EQ(image.at(x, y), round16(static_cast<std::uint32_t>(grey16_value(x, y))))
                << "at " << x << "," << y;
        }
    }
}

// ---------------------------------------------------------------------------
// JPEG
// ---------------------------------------------------------------------------

TEST(ImageIO, DetectsJpegAndDecodesBaseline) {
    const ImageInfo info = read_image_info(fixture("baseline.jpg"));
    EXPECT_EQ(info.format, ImageFormat::Jpeg);
    EXPECT_EQ(info.width, 64);
    EXPECT_EQ(info.height, 48);
    EXPECT_EQ(info.channels, 3);
    EXPECT_EQ(info.bit_depth, 8);

    const Image image = read_image(fixture("baseline.jpg"));
    ASSERT_EQ(image.channels(), 3);
    // JPEG is lossy, so compare to the source within a tolerance. The fixture
    // is a smooth ramp specifically so this bound can stay tight: if it ever
    // needs loosening, the fixture or the decoder changed, not the tolerance.
    int worst = 0;
    for (int y = 0; y < 48; ++y) {
        for (int x = 0; x < 64; ++x) {
            int expected[3];
            rgb_jpeg_value(x, y, expected);
            for (int c = 0; c < 3; ++c) {
                const int delta = std::abs(static_cast<int>(image.at(x, y, c)) - expected[c]);
                worst = std::max(worst, delta);
            }
        }
    }
    EXPECT_LE(worst, 16) << "largest per-channel error across the image";
}

TEST(ImageIO, CameraJpegsDecodeAtExpectedSize) {
    // The 200x150 camera fixtures are also valid baseline JPEGs; this confirms
    // the codec handles the colour-subsampled, Exif-bearing form.
    for (const char* name : {"cam_a1.jpg", "cam_a2.jpg", "cam_b1.jpg"}) {
        const ImageInfo info = read_image_info(fixture(name));
        EXPECT_EQ(info.format, ImageFormat::Jpeg) << name;
        EXPECT_EQ(info.width, 200) << name;
        EXPECT_EQ(info.height, 150) << name;
        EXPECT_EQ(info.channels, 3) << name;

        const Image image = read_image(fixture(name));
        EXPECT_EQ(image.width(), 200) << name;
        EXPECT_EQ(image.height(), 150) << name;
        EXPECT_EQ(image.channels(), 3) << name;
    }
}

// ---------------------------------------------------------------------------
// Detection by magic bytes
// ---------------------------------------------------------------------------

TEST(ImageIO, DetectsByMagicNotExtension) {
    // A PNG named ".jpg" must still be reported (and decoded) as PNG.
    TempDir dir("mislabeled");
    const std::vector<std::uint8_t> png = read_bytes(fixture("rgb.png"));
    const std::string disguised = dir.path("photo.jpg");
    write_bytes(disguised, png);

    EXPECT_EQ(detect_image_format(disguised), ImageFormat::Png);
    const ImageInfo info = read_image_info(disguised);
    EXPECT_EQ(info.format, ImageFormat::Png);
    const Image image = read_image(disguised);
    EXPECT_EQ(image.width(), 64);
    EXPECT_EQ(image.channels(), 3);

    // The reverse: a JPEG named ".png".
    const std::vector<std::uint8_t> jpeg = read_bytes(fixture("baseline.jpg"));
    const std::string disguised2 = dir.path("photo.png");
    write_bytes(disguised2, jpeg);
    EXPECT_EQ(detect_image_format(disguised2), ImageFormat::Jpeg);
}

TEST(ImageIO, DetectsEveryFixtureByMagic) {
    EXPECT_EQ(detect_image_format(fixture("rgb.png")), ImageFormat::Png);
    EXPECT_EQ(detect_image_format(fixture("rgb8.tiff")), ImageFormat::Tiff);
    EXPECT_EQ(detect_image_format(fixture("baseline.jpg")), ImageFormat::Jpeg);
    EXPECT_EQ(detect_image_format(fixture("fixture_a.pgm")), ImageFormat::Pnm);
}

TEST(ImageIO, UnknownFileIsUnknown) {
    TempDir dir("unknown");
    const std::string path = dir.path("mystery.bin");
    write_bytes(path, {'H', 'E', 'L', 'L', 'O', 'W', 'O', 'R', 'L', 'D'});
    EXPECT_EQ(detect_image_format(path), ImageFormat::Unknown);
    EXPECT_THROW(read_image_info(path), Error);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, MissingFileIsUnknownAndThrows) {
    TempDir dir("missing");
    const std::string path = dir.path("does_not_exist.png");
    EXPECT_EQ(detect_image_format(path), ImageFormat::Unknown);
    EXPECT_THROW(read_image_info(path), Error);
    EXPECT_THROW(read_image(path), Error);
}

// ---------------------------------------------------------------------------
// Garbage and truncation must throw, never crash
// ---------------------------------------------------------------------------

TEST(ImageIO, TruncatedPngThrows) {
    TempDir dir("trunc_png");
    std::vector<std::uint8_t> png = read_bytes(fixture("rgb.png"));
    ASSERT_GT(png.size(), 20U);
    png.resize(png.size() / 2);
    const std::string path = dir.path("truncated.png");
    write_bytes(path, png);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, TruncatedJpegThrows) {
    TempDir dir("trunc_jpeg");
    std::vector<std::uint8_t> jpeg = read_bytes(fixture("baseline.jpg"));
    ASSERT_GT(jpeg.size(), 20U);
    jpeg.resize(jpeg.size() / 3);
    const std::string path = dir.path("truncated.jpg");
    write_bytes(path, jpeg);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, TruncatedTiffThrows) {
    TempDir dir("trunc_tiff");
    std::vector<std::uint8_t> tiff = read_bytes(fixture("rgb8.tiff"));
    ASSERT_GT(tiff.size(), 20U);
    tiff.resize(16);  // header only, no pixel data
    const std::string path = dir.path("truncated.tiff");
    write_bytes(path, tiff);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, GarbageWithPngSignatureThrows) {
    TempDir dir("garbage_png");
    // A valid PNG signature followed by noise: detection succeeds, decoding
    // must fail cleanly.
    std::vector<std::uint8_t> bytes = {0x89, 'P', 'N', 'G', '\r', '\n', 0x1A, '\n'};
    for (int i = 0; i < 64; ++i) {
        bytes.push_back(static_cast<std::uint8_t>((i * 37 + 11) % 256));
    }
    const std::string path = dir.path("garbage.png");
    write_bytes(path, bytes);
    EXPECT_EQ(detect_image_format(path), ImageFormat::Png);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, GarbageWithJpegSignatureThrows) {
    TempDir dir("garbage_jpeg");
    std::vector<std::uint8_t> bytes = {0xFF, 0xD8, 0xFF};
    for (int i = 0; i < 64; ++i) {
        bytes.push_back(static_cast<std::uint8_t>((i * 53 + 7) % 256));
    }
    const std::string path = dir.path("garbage.jpg");
    write_bytes(path, bytes);
    EXPECT_EQ(detect_image_format(path), ImageFormat::Jpeg);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, GarbageWithTiffSignatureThrows) {
    TempDir dir("garbage_tiff");
    // Little-endian TIFF header claiming an IFD beyond the end of the file.
    std::vector<std::uint8_t> bytes = {'I', 'I', 0x2A, 0x00, 0xFF, 0xFF, 0x00, 0x00};
    const std::string path = dir.path("garbage.tiff");
    write_bytes(path, bytes);
    EXPECT_EQ(detect_image_format(path), ImageFormat::Tiff);
    EXPECT_THROW(read_image(path), Error);
}

TEST(ImageIO, EmptyFileThrows) {
    TempDir dir("empty");
    const std::string path = dir.path("empty.png");
    write_bytes(path, {});
    EXPECT_EQ(detect_image_format(path), ImageFormat::Unknown);
    EXPECT_THROW(read_image(path), Error);
}

// ---------------------------------------------------------------------------
// PNM still works through the new dispatch
// ---------------------------------------------------------------------------

TEST(ImageIO, PnmRoundTripsThroughReadImage) {
    // Write with the existing writer, read back through the new entry point.
    TempDir dir("pnm");
    const std::string path = dir.path("written.pgm");
    Image image(32, 24, 1);
    for (int y = 0; y < 24; ++y) {
        for (int x = 0; x < 32; ++x) {
            image.at(x, y) = static_cast<std::uint8_t>((x * 3 + y * 5) % 256);
        }
    }
    write_pnm(image, path);

    EXPECT_EQ(detect_image_format(path), ImageFormat::Pnm);
    const ImageInfo info = read_image_info(path);
    EXPECT_EQ(info.format, ImageFormat::Pnm);
    EXPECT_EQ(info.width, 32);
    EXPECT_EQ(info.height, 24);
    EXPECT_EQ(info.channels, 1);
    EXPECT_EQ(info.bit_depth, 8);

    const Image decoded = read_image(path);
    ASSERT_EQ(decoded.width(), 32);
    ASSERT_EQ(decoded.channels(), 1);
    for (int y = 0; y < 24; ++y) {
        for (int x = 0; x < 32; ++x) {
            ASSERT_EQ(decoded.at(x, y), image.at(x, y));
        }
    }
}

TEST(ImageIO, CommittedPnmFixtureDecodes) {
    const Image image = read_image(fixture("fixture_a.pgm"));
    EXPECT_EQ(image.width(), 200);
    EXPECT_EQ(image.height(), 150);
    EXPECT_EQ(image.channels(), 1);
}

// ---------------------------------------------------------------------------
// PNG encoding
// ---------------------------------------------------------------------------

/// Encode -> decode a greyscale page: the pixels must come back exactly, and
/// the encoded stream must be a decodable PNG of the same geometry.
TEST(ImageIO, PngEncodeDecodeRoundTripsGrey) {
    TempDir dir("pngenc_grey");
    Image image(37, 21, 1);
    for (int y = 0; y < 21; ++y) {
        for (int x = 0; x < 37; ++x) {
            image.at(x, y) = static_cast<std::uint8_t>((x * 5 + y * 13 + 3) % 256);
        }
    }
    const std::string path = dir.path("encoded.png");
    write_png(path, image);

    EXPECT_EQ(detect_image_format(path), ImageFormat::Png);
    const ImageInfo info = read_image_info(path);
    EXPECT_EQ(info.format, ImageFormat::Png);
    EXPECT_EQ(info.width, 37);
    EXPECT_EQ(info.height, 21);
    EXPECT_EQ(info.channels, 1);
    EXPECT_EQ(info.bit_depth, 8);

    const Image decoded = read_image(path);
    ASSERT_EQ(decoded.channels(), 1);
    for (int y = 0; y < 21; ++y) {
        for (int x = 0; x < 37; ++x) {
            ASSERT_EQ(decoded.at(x, y), image.at(x, y)) << "at " << x << "," << y;
        }
    }
}

/// Encode -> decode an RGB page, byte-exact. Exercises the 3-channel path that
/// the texturing stage writes.
TEST(ImageIO, PngEncodeDecodeRoundTripsRgb) {
    TempDir dir("pngenc_rgb");
    Image image(24, 19, 3);
    for (int y = 0; y < 19; ++y) {
        for (int x = 0; x < 24; ++x) {
            image.at(x, y, 0) = static_cast<std::uint8_t>((x * 3 + y) % 256);
            image.at(x, y, 1) = static_cast<std::uint8_t>((x + y * 5) % 256);
            image.at(x, y, 2) = static_cast<std::uint8_t>((x * 7 + y * 11) % 256);
        }
    }
    const std::string path = dir.path("encoded.png");
    write_png(path, image);

    const Image decoded = read_image(path);
    ASSERT_EQ(decoded.width(), 24);
    ASSERT_EQ(decoded.height(), 19);
    ASSERT_EQ(decoded.channels(), 3);
    for (int y = 0; y < 19; ++y) {
        for (int x = 0; x < 24; ++x) {
            for (int c = 0; c < 3; ++c) {
                ASSERT_EQ(decoded.at(x, y, c), image.at(x, y, c))
                    << "at " << x << "," << y << " channel " << c;
            }
        }
    }
}

/// The in-memory encoder agrees with the file writer: encode_png's bytes are a
/// PNG that png_decode reads back to the same pixels, with no file involved.
TEST(ImageIO, EncodePngBytesDecodeInMemory) {
    Image image(8, 8, 3);
    for (int y = 0; y < 8; ++y) {
        for (int x = 0; x < 8; ++x) {
            image.at(x, y, 0) = static_cast<std::uint8_t>(x * 30);
            image.at(x, y, 1) = static_cast<std::uint8_t>(y * 30);
            image.at(x, y, 2) = static_cast<std::uint8_t>(128);
        }
    }
    const std::vector<std::uint8_t> bytes = encode_png(image);
    ASSERT_GE(bytes.size(), 8U);
    EXPECT_EQ(bytes[0], 0x89);
    EXPECT_EQ(bytes[1], 'P');
    EXPECT_EQ(bytes[2], 'N');
    EXPECT_EQ(bytes[3], 'G');

    // Decode through the file entry point by writing the bytes back out, which
    // also proves the two entry points share one encoder.
    TempDir dir("pngenc_mem");
    const std::string path = dir.path("mem.png");
    write_bytes(path, bytes);
    const Image decoded = read_image(path);
    ASSERT_EQ(decoded.channels(), 3);
    for (int y = 0; y < 8; ++y) {
        for (int x = 0; x < 8; ++x) {
            for (int c = 0; c < 3; ++c) {
                ASSERT_EQ(decoded.at(x, y, c), image.at(x, y, c));
            }
        }
    }
}

/// Encoding a 4-channel image is supported by the encoder even though Image
/// itself only builds 1- and 3-channel data, and a 2-channel request is invalid.
TEST(ImageIO, EncodePngRejectsUnsupportedChannelCount) {
    Image image(4, 4, 1);
    EXPECT_NO_THROW(static_cast<void>(encode_png(image)));
    // Image's constructor already refuses 2 channels, so the only reachable
    // invalid states are geometrically empty images.
    const Image empty;
    EXPECT_THROW(static_cast<void>(encode_png(empty)), Error);
}

// ---------------------------------------------------------------------------
// read_image_info agrees with read_image for every fixture
// ---------------------------------------------------------------------------

TEST(ImageIO, InfoDimensionsMatchDecodedDimensions) {
    std::vector<const char*> names = {"grey.png",     "rgb.png",     "rgba.png",    "palette.png",
                                      "grey16.png",   "rgb8.tiff",   "grey16.tiff", "baseline.jpg",
                                      "palette.tiff", "exif_grey.tiff", "cam_a1.jpg", "cam_a2.jpg",
                                      "cam_b1.jpg"};
    for (const char* extra : {"grey16_tiled.tiff", "rgb8_be.tiff"}) {
        if (std::filesystem::exists(fixture(extra))) {
            names.push_back(extra);
        }
    }
    for (const char* name : names) {
        const ImageInfo info = read_image_info(fixture(name));
        const Image image = read_image(fixture(name));
        EXPECT_EQ(info.width, image.width()) << name;
        EXPECT_EQ(info.height, image.height()) << name;
        // The decode narrows to 1 or 3 channels; the info reports the stored
        // count, which the interface limits to 1, 3 or 4.
        EXPECT_GE(info.channels, 1) << name;
        EXPECT_LE(info.channels, 4) << name;
        EXPECT_TRUE(image.channels() == 1 || image.channels() == 3) << name;
    }
}

TEST(ImageIO, ReadInfoDoesNotNeedPixelDataToBeValid) {
    // read_image_info reads only the chunks up to IDAT, so a file whose IDAT
    // payload is cut short must still report its dimensions, while read_image
    // (which needs the pixels) must fail.
    TempDir dir("info_only");
    const std::vector<std::uint8_t> png = read_bytes(fixture("rgb.png"));

    // Walk the chunk list to find IDAT, then keep everything up to and
    // including IDAT's 8-byte header, dropping the pixel data itself.
    std::size_t pos = 8;
    std::size_t header_only = 0;
    while (pos + 8 <= png.size()) {
        const std::uint32_t length = (static_cast<std::uint32_t>(png[pos]) << 24) |
                                     (static_cast<std::uint32_t>(png[pos + 1]) << 16) |
                                     (static_cast<std::uint32_t>(png[pos + 2]) << 8) |
                                     static_cast<std::uint32_t>(png[pos + 3]);
        const bool is_idat = png[pos + 4] == 'I' && png[pos + 5] == 'D' && png[pos + 6] == 'A' &&
                             png[pos + 7] == 'T';
        if (is_idat) {
            header_only = pos + 8;
            break;
        }
        pos += 8 + length + 4;
    }
    ASSERT_GT(header_only, 0U);

    std::vector<std::uint8_t> truncated(png.begin(),
                                        png.begin() + static_cast<std::ptrdiff_t>(header_only));
    const std::string path = dir.path("header_only.png");
    write_bytes(path, truncated);

    const ImageInfo info = read_image_info(path);
    EXPECT_EQ(info.width, 64);
    EXPECT_EQ(info.height, 48);
    EXPECT_EQ(info.channels, 3);
    EXPECT_THROW(read_image(path), Error);
}

